$(function(){var s=$(window);s.on("load",function(){var a=s.scrollTop(),e=$(".topbar");40<a?e.addClass("fixed-header"):e.removeClass("fixed-header")}),$(window).scroll(function(){50<=$(window).scrollTop()?$(".topbar").addClass("fixed-header"):$(".topbar").removeClass("fixed-header")}),$(".banner-carousal").owlCarousel({items:1,loop:!0,margin:100,autoplay:!1,autoplayTimeout:1500,autoplayHoverPause:!0,nav:!0,navText:[$(".prev"),$(".next")]}),$(".collapse.show").each(function(){$(this).prev(".acc-title").find(".fas").addClass("fa-minus-circle").removeClass("fa-plus-circle").parent().parent().parent().addClass("active")}),$(".collapse").on("show.bs.collapse",function(){$(this).prev(".acc-title").find(".fas").removeClass("fa-plus-circle").addClass("fa-minus-circle").parent().parent().parent().addClass("active")}).on("hide.bs.collapse",function(){$(this).prev(".acc-title").find(".fas").removeClass("fa-minus-circle").addClass("fa-plus-circle").parent().parent().parent().removeClass("active")})});